int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("session required");auto graph=loadGraph(argv[1]);RetainedShotTimelineCandidate timeline(graph,2237);std::map<std::string,SfmModelGeometryCandidate>cache;std::filesystem::path content=R"(D:\SteamLibrary\steamapps\common\SourceFilmmaker\game\usermod)";auto asset=[&](const std::string&name)->const SfmModelGeometryCandidate&{auto found=cache.find(name);if(found!=cache.end())return found->second;auto path=content/name;path.replace_extension();auto read=[](const std::filesystem::path&p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("scene asset missing");return std::vector<uint8_t>((std::istreambuf_iterator<char>(f)),{});};return cache.emplace(name,readSfmModelGeometryCandidate(read(path.string()+".mdl"),read(path.string()+".vvd"),read(path.string()+".dx90.vtx"))).first->second;};auto skeleton=[&](const std::string&name)->const std::vector<GeometryBoneCandidate>&{return asset(name).bones;};std::ifstream gameinfo(content/"gameinfo.txt",std::ios::binary);if(!gameinfo)throw std::runtime_error("scene GameInfo missing");std::string gameinfoText((std::istreambuf_iterator<char>(gameinfo)),{});SceneRenderInputsCacheCandidate materialCache(gameinfoMountsCandidate(gameinfoText,content,content.parent_path()),2,asset);size_t materialFailures=0;const ModelRenderInputsCandidate*retainedMaterial=nullptr;GeometryDeformationWorkerPoolCandidate workers(4);size_t frames=0;for(int32_t tick:{1392000,1392167,1392333}){auto step=evaluateLiveSessionSceneCandidate(timeline,tick,512,512);auto poses=readSessionScenePosesCandidate(timeline.graph(),step.scene,skeleton,true,true);auto geometry=prepareSceneGeometryCandidate(poses,asset,workers);if(geometry.size()!=3)throw std::runtime_error("scene geometry model count");for(const auto&instance:geometry){try{const auto&input=materialCache.get(instance.model.placement.asset,instance.model.skin,instance.model.body);if(instance.model.id!=34561)throw std::runtime_error("unexpected resolved scene materials");if(retainedMaterial&&retainedMaterial!=&input)throw std::runtime_error("material cache reference changed");retainedMaterial=&input;}catch(const std::runtime_error&e){if(instance.model.id==34561)throw;const std::string message=e.what();if(message.find("texture")==std::string::npos)throw;std::cout<<"material_pending model="<<instance.model.id<<" reason="<<message<<"\n";++materialFailures;}}size_t total=0;for(size_t modelIndex=0;modelIndex<geometry.size();++modelIndex){auto&model=geometry[modelIndex];auto&source=asset(model.model.placement.asset);auto palette=evaluateGeometryPosePaletteCandidate(source.bones,poses.models[modelIndex].locals);auto scalar=deformGeometryBatchCandidate(source.geometry,palette,0);if(scalar.size()!=model.vertices.size())throw std::runtime_error("scalar scene count");for(size_t n=0;n<scalar.size();++n){auto expected=model.model.placement.matrix.clip(scalar[n].position);for(size_t k=0;k<3;++k)if(std::memcmp(&expected[k],&model.vertices[n].position[k],4))throw std::runtime_error("world position differs from scalar");if(scalar[n].hasTangent&&scalar[n].tangent[3]!=model.vertices[n].tangent[3])throw std::runtime_error("tangent handedness changed");}total+=model.vertices.size();for(auto&vertex:model.vertices)for(auto value:vertex.position)if(!std::isfinite(value))throw std::runtime_error("scene position nonfinite");}std::vector<ModelRenderInputsCandidate> topology;for(auto&instance:geometry){auto&source=asset(instance.model.placement.asset);ModelRenderInputsCandidate input;input.materials.resize(1);for(auto&mesh:source.meshes){if(mesh.model!=0)continue;input.ranges.push_back({uint32_t(input.indices.size()),uint32_t(mesh.triangles.size()*3),0,mesh.body,mesh.model,mesh.mesh});for(auto&triangle:mesh.triangles)for(auto vertex:triangle)input.indices.push_back(vertex);}topology.push_back(std::move(input));}auto upload=prepareSceneGpuUploadCandidate(geometry,topology,[](const auto&v){return double(v.position[2]);});if(upload.vertices.size()!=total||!upload.translucent.empty())throw std::runtime_error("scene upload count");size_t vertexStart=0,indexStart=0;for(size_t m=0;m<geometry.size();++m){for(size_t n=0;n<geometry[m].vertices.size();++n){auto&actual=upload.vertices[vertexStart+n];auto&expected=geometry[m].vertices[n];if(actual.position!=expected.position||actual.normal!=expected.normal||actual.uv!=expected.uv)throw std::runtime_error("scene upload vertex");}for(size_t n=0;n<topology[m].indices.size();++n)if(upload.indices[indexStart+n]!=vertexStart+topology[m].indices[n])throw std::runtime_error("scene upload rebase");vertexStart+=geometry[m].vertices.size();indexStart+=topology[m].indices.size();}for(auto&draw:upload.opaque){auto&r=topology[draw.model].ranges[draw.range];size_t offset=0;for(size_t m=0;m<draw.model;++m)offset+=topology[m].indices.size();if(draw.firstIndex!=offset+r.firstIndex||draw.indexCount!=r.indexCount||draw.materialIndex!=r.materialIndex)throw std::runtime_error("scene upload draw");}std::cout<<"packed_indices="<<upload.indices.size()<<" packed_draws="<<upload.opaque.size()<<" topology_only=1 ";std::cout<<"tick="<<tick<<" models="<<geometry.size()<<" vertices="<<total<<"\n";++frames;}if(materialCache.size()!=1||materialCache.hits()!=2||materialFailures!=6)throw std::runtime_error("retained material coverage");std::cout<<"retained_material_entries="<<materialCache.size()<<" cache_hits="<<materialCache.hits()<<" unresolved_texture_attempts="<<materialFailures<<"\n";std::cout<<"scene CPU geometry gpu_vertex_pack_exact=1 global_indices_exact=1 draw_offsets_exact=1 scalar_positions_exact=1 tangent_handedness_preserved=1 passed frames="<<frames<<" asset_loads="<<cache.size()<<" retained_workers="<<workers.workerCount()<<" scaled_normal_parity=unverified materials_and_gpu_scene=unfinished\n";return 0;}catch(std::exception&e){std::cerr<<e.what();return 1;}}
